package com.roughpath.alpha;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.Build;import android.provider.MediaStore;import android.webkit.*;import java.io.*;import java.net.*;import org.json.JSONObject;
/** Allowlisted public market data bridge and user-initiated report export. */
public class ResearchBridge {
 private final Activity activity;private final WebView web;private final java.util.concurrent.ExecutorService network=java.util.concurrent.Executors.newFixedThreadPool(3);
 ResearchBridge(Activity a,WebView w){activity=a;web=w;}
 private final java.util.concurrent.ExecutorService publicNetwork=java.util.concurrent.Executors.newFixedThreadPool(4);
 void close(){network.shutdownNow();publicNetwork.shutdownNow();}
 @JavascriptInterface public void get(int id,String url){network.execute(()->{String raw="",error="";HttpURLConnection c=null;try{URL u=new URL(url);if(!u.getProtocol().equals("https")||!u.getHost().equals("api.exchange.coinbase.com")||u.getPort()!=-1||!u.getPath().matches("/products/[A-Z0-9]{1,20}-USD/(candles|trades)")||u.getUserInfo()!=null)throw new IOException("Endpoint denied");c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","RoughPathAlpha/1.0");if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>4000000)throw new IOException("Response too large");}}raw=out.toString("UTF-8");}catch(Exception e){error=e.getMessage()==null?"Network error":e.getMessage();}finally{if(c!=null)c.disconnect();}final String script="researchNativeReply("+id+","+JSONObject.quote(raw)+","+JSONObject.quote(error)+")";activity.runOnUiThread(()->{if(!activity.isDestroyed())web.evaluateJavascript(script,null);});});}
 @JavascriptInterface public void read(int id,String url){publicNetwork.execute(()->{String raw="",error="";HttpURLConnection c=null;try{if(!PublicDataPolicy.allows(url))throw new IOException("Public data endpoint denied");URL u=new URL(url);NetworkTrace.log(url,"connecting","Native HTTPS read");c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setRequestProperty("User-Agent","RoughPathAlpha/1.6");int status=c.getResponseCode();if(status!=200)throw new IOException("HTTP "+status);long total=c.getContentLengthLong();ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[16384];int n;long last=0;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>16000000)throw new IOException("Response too large");long now=System.currentTimeMillis();if(now-last>300){last=now;final int bytes=out.size();activity.runOnUiThread(()->{if(!activity.isDestroyed())web.evaluateJavascript("networkNativeProgress("+id+","+bytes+","+total+")",null);});}}}raw=out.toString("UTF-8");NetworkTrace.log(url,"healthy","Read "+out.size()+" bytes");}catch(Exception e){error=e.getClass().getSimpleName()+": "+(e.getMessage()==null?"Read failed":e.getMessage());NetworkTrace.log(url,"error",error);}finally{if(c!=null)c.disconnect();}final String script="networkNativeReply("+id+","+JSONObject.quote(raw)+","+JSONObject.quote(error)+")";activity.runOnUiThread(()->{if(!activity.isDestroyed())web.evaluateJavascript(script,null);});});}
 @JavascriptInterface public void importFile(){activity.runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("application/json");intent.addCategory(Intent.CATEGORY_OPENABLE);activity.startActivityForResult(intent,41);});}
 void importUri(Uri uri){network.execute(()->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=activity.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Unable to open file");byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>32000000)throw new IOException("Import limit is 32 MB");}}final String s=out.toString("UTF-8");activity.runOnUiThread(()->{if(!activity.isDestroyed())web.evaluateJavascript("importResearch("+JSONObject.quote(s)+")",null);});}catch(Exception e){report("Import failed: "+e.getMessage());}});}
 @JavascriptInterface public void download(String name,String content){if(!name.matches("[A-Za-z0-9._-]+")||content.length()>32000000)return;network.execute(()->{try{if(Build.VERSION.SDK_INT<29)throw new IOException("Report export requires Android 10+");ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,name);v.put(MediaStore.Downloads.MIME_TYPE,"application/json");v.put(MediaStore.Downloads.IS_PENDING,1);Uri uri=activity.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("Cannot create Downloads file");try(OutputStream out=activity.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Cannot write Downloads file");out.write(content.getBytes("UTF-8"));}v.clear();v.put(MediaStore.Downloads.IS_PENDING,0);activity.getContentResolver().update(uri,v,null,null);report("Report saved to Downloads");}catch(Exception e){report("Export failed: "+e.getMessage());}});}
 private void report(String msg){activity.runOnUiThread(()->{if(!activity.isDestroyed())web.evaluateJavascript("researchProgress(0,1,"+JSONObject.quote(msg)+")",null);});}
}
